_id" value="<?= (int)$contract['preventivo_id'] ?>"><div class="col-12"><div class="alert alert-info mb-0">Preventivo #<?= (int)$contract['preventivo_id'] ?> collegato. Cliente, sede e prezzo sono stati precompilati: controllali prima di salvare.</div></div><?php endif ?><div class="col-md-6"><label class="form-label">Stato<select class="form-select" name="stato"><?php foreach(['bozza'=>'Bozza','da_accettare'=>'Da accettare','attivo'=>'Attivo','sospeso'=>'Sospeso','scaduto'=>'Scaduto','cessato'=>'Cessato'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $contract['stato']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label></div>
